{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-07-09/server.schema.json",
  "name": "io.github.roshan-research/roshan-baaz-mcp",
  "description": "Self-hostable MCP server for Roshan AI's Baaz (باز) Persian semantic-search service.",
  "version": "0.1.0",
  "homepage": "https://github.com/roshan-research/roshan-baaz-mcp",
  "documentation": "https://docs.roshan-ai.ir",
  "license": "MIT",
  "runtime": "python",
  "packages": [
    {
      "registryType": "pypi",
      "identifier": "roshan-baaz-mcp",
      "version": "0.1.0",
      "transport": { "type": "stdio" }
    }
  ],
  "command": "python",
  "args": ["-m", "roshan_baaz_mcp"],
  "env": [
    {
      "name": "ROSHAN_BAAZ_BASE_URL",
      "description": "Base URL of the Baaz deployment (shorthand single-instance config).",
      "default": "https://baaz.roshan-ai.ir",
      "required": false
    },
    {
      "name": "ROSHAN_BAAZ_TOKEN",
      "description": "Auth token sent as 'Authorization: Token <token>' (shorthand config).",
      "required": false,
      "secret": true
    },
    {
      "name": "ROSHAN_BAAZ__DEFAULT_INSTANCE",
      "description": "Name of the instance used when a tool omits 'instance'.",
      "default": "default",
      "required": false
    },
    {
      "name": "ROSHAN_BAAZ__INSTANCES__<NAME>__BASE_URL",
      "description": "Base URL for a named instance (nested multi-instance config).",
      "required": false
    },
    {
      "name": "ROSHAN_BAAZ__INSTANCES__<NAME>__TOKEN",
      "description": "Auth token for a named instance.",
      "required": false,
      "secret": true
    },
    {
      "name": "ROSHAN_BAAZ__LOG_LEVEL",
      "description": "Logging level (DEBUG, INFO, WARNING, ...).",
      "default": "INFO",
      "required": false
    }
  ],
  "tools": [
    { "name": "baaz_index", "description": "Index/update a batch of documents (POST /{index}/index)." },
    { "name": "baaz_semantic_search", "description": "Semantic query over an index (POST /{index}/document/semantic_query)." },
    { "name": "baaz_document_status", "description": "Check whether documents exist by URL (POST /{index}/document_status)." },
    { "name": "baaz_delete_index", "description": "Delete an entire index (DELETE /{index}/delete_index)." },
    { "name": "baaz_delete_documents", "description": "Delete documents of a type (DELETE /{index}/delete_index with body)." },
    { "name": "baaz_stats", "description": "Index statistics (GET /{index}/stats)." },
    { "name": "baaz_similar_documents", "description": "Find similar documents (POST /{index}/similar/documents)." },
    { "name": "baaz_view_document", "description": "Fetch a full document by id (GET /{index}/document/view?id=)." },
    { "name": "healthcheck", "description": "Check that an instance is up (GET /healthcheck)." },
    { "name": "list_instances", "description": "List configured instances (names + base URLs only, never tokens)." },
    { "name": "roshan_baaz_docs", "description": "Offline documentation about Baaz and these tools." }
  ]
}
